wal2-footer-background: transparent;\n  --swal2-footer-color: inherit;\n\n  // TIMER PROGRESS BAR\n  --swal2-timer-progress-bar-background: rgba(0, 0, 0, 0.3);\n\n  // CLOSE BUTTON\n  --swal2-close-button-position: initial;\n  --swal2-close-button-inset: auto;\n  --swal2-close-button-font-size: 2.5em;\n  --swal2-close-button-color: #ccc;\n  --swal2-close-button-transition: color 0.2s, box-shadow 0.2s;\n  --swal2-close-button-outline: initial;\n  --swal2-close-button-box-shadow: inset 0 0 0 3px transparent;\n  --swal2-close-button-focus-box-shadow: inset var(--swal2-outline);\n\n  // CLOSE BUTTON:HOVER\n  --swal2-close-button-hover-transform: none;\n\n  // ACTIONS\n  --swal2-actions-justify-content: center;\n  --swal2-actions-width: auto;\n  --swal2-actions-margin: 1.25em auto 0;\n  --swal2-actions-padding: 0;\n  --swal2-actions-border-radius: 0;\n  --swal2-actions-background: transparent;\n\n  // COMMON VARIABLES FOR ALL ACTION BUTTONS\n  --swal2-action-button-transition: background-color 0.2s, box-shadow 0.2s;\n  --swal2-action-button-hover: black 10%;\n  --swal2-action-button-active: black 10%;\n\n  // CONFIRM BUTTON\n  --swal2-confirm-button-box-shadow: none;\n  --swal2-confirm-button-border-radius: 0.25em;\n  --swal2-confirm-button-background-color: #7066e0;\n  --swal2-confirm-button-color: #fff;\n\n  // DENY BUTTON\n  --swal2-deny-button-box-shadow: none;\n  --swal2-deny-button-border-radius: 0.25em;\n  --swal2-deny-button-background-color: #dc3741;\n  --swal2-deny-button-color: #fff;\n\n  // CANCEL BUTTON\n  --swal2-cancel-button-box-shadow: none;\n  --swal2-cancel-button-border-radius: 0.25em;\n  --swal2-cancel-button-background-color: #6e7881;\n  --swal2-cancel-button-color: #fff;\n\n  // TOASTS\n  --swal2-toast-show-animation: swal2-toast-show 0.5s;\n  --swal2-toast-hide-animation: swal2-toast-hide 0.1s forwards;\n  --swal2-toast-border: none;\n  --swal2-toast-box-shadow:\n    0 0 1px hsl(0deg 0% 0% / 0.075), 0 1px 2px hsl(0deg 0% 0% / 0.075), 1px 2px 4px hsl(0deg 0% 0% / 0.075),\n    1px 3px 8px hsl(0deg 0% 0% / 0.075), 2px 4px 16px hsl(0deg 0% 0% / 0.075);\n}\n\n// DARK THEME\n@mixin dark-theme {\n  --swal2-dark-theme-black: #19191a;\n  --swal2-dark-theme-white: #e1e1e1;\n\n  // POPUP\n  --swal2-background: var(--swal2-dark-theme-black);\n  --swal2-color: var(--swal2-dark-theme-white);\n  --swal2-footer-border-color: #555;\n\n  // INPUT\n  --swal2-input-background: color-mix(in srgb, var(--swal2-dark-theme-black), var(--swal2-dark-theme-white) 10%);\n\n  // VALIDATION MESSAGE\n  --swal2-validation-message-background: color-mix(\n    in srgb,\n    var(--swal2-dark-theme-black),\n    var(--swal2-dark-theme-white) 10%\n  );\n  --swal2-validation-message-color: var(--swal2-dark-theme-white);\n\n  // TIMER PROGRESS BAR\n  --swal2-timer-progress-bar-background: rgba(255, 255, 255, 0.7);\n}\n\n[data-swal2-theme='dark'] {\n  @include dark-theme;\n}\n\n// AUTO THEME, based on prefers-color-scheme\n@media (prefers-color-scheme: dark) {\n  [data-swal2-theme='auto'] {\n    @include dark-theme;\n  }\n}\n\n$swal2-outline-color: rgba(100, 150, 200, 0.5) !default;\n\n// CONTAINER\n$swal2-container-padding: var(--swal2-container-padding) !default;\n\n// BACKDROP\n$swal2-backdrop: var(--swal2-backdrop) !default;\n$swal2-backdrop-transition: var(--swal2-backdrop-transition) !default;\n\n// POPUP\n$swal2-width: var(--swal2-width) !default;\n$swal2-padding: var(--swal2-padding) !default;\n$swal2-border: var(--swal2-border) !default;\n$swal2-border-radius: var(--swal2-border-radius) !default;\n$swal2-background: var(--swal2-background) !default;\n$swal2-color: var(--swal2-color) !default;\n\n// ANIMATIONS\n$swal2-show-animation: var(--swal2-show-animation) !default;\n$swal2-hide-animation: var(--swal2-hide-animation) !default;\n\n// TYPOGRAPHY\n$swal2-font: inherit !default;\n$swal2-font-size: 1rem !default;\n\n// ICONS\n$swal2-icon-margin: 2.5em auto 0.6em !default;\n$swal2-icon-font-family: inherit !default;\n$swal2-icon-font-size: 3.7